with RecursiveCte DownsizedPosts as (
    select top 50000 p.Id, p.PostTypeId, p.ParentId, p.Title, p.Body, p.Score, p.ViewCount, p.CreationDate, p.OwnerUserId,
      dense_rank() over (partition by p.PostTypeId order by p.Score desc, p.ViewCount desc) as RankPerType        
    from Posts p
    where p.CreationDate > dateadd(year, -2, getdate()) and p.OwnerUserId is not null 
    
    union all
    
    select c.Id, c.PostTypeId, c.ParentId, c.Title, c.Body, c.Score, c.ViewCount, c.CreationDate, c.OwnerUserId, rsp.RankPerType + 10000
    from Posts c
    inner join DownsizedPosts rsp on rsp.Id = c.ParentId  
    where c.PostTypeId = 2 and rsp.RankPerType < 100				   					
